import {
  Sprite,
  SpriteMaterial,
  Texture,
  PlaneGeometry
} from 'three/webgpu';

export default function createNode(config, ctx) {
  // Load the texture (synchronous – pre‑cached by the loader)
  const texture = ctx.textureLoader(config.assets.imageUrl);

  // Material using standard SpriteMaterial (no custom shader required)
  const material = new SpriteMaterial({
    map: texture,
    transparent: true,
    depthWrite: false,
    // SpriteMaterial automatically billboards
  });

  // Create the sprite
  const sprite = new Sprite(material);
  sprite.position.set(0, -0.3, 0);
  sprite.rotation.set(0, 0, 0);
  sprite.scale.set(1, 1, 1);

  // User‑data for event handlers (none defined)
  sprite.userData.handlers = {};

  // Cleanup: dispose material, texture, and the sprite’s internal geometry
  sprite.userData.cleanup = () => {
    material.dispose();
    texture.dispose();
    if (sprite.geometry) sprite.geometry.dispose();
  };

  // No cinematic primitives to apply – spec lists none

  return sprite;
}
